'       '''' V_SOURCE_USER_ID,',
'       PERMISSIONS_TYPE',
'from STS_SCOPE',
'where REFERENCE_TYPE = ''FOLDER_CLASS''',
'  and REFERENCE_ID = :P103_FOLDER_CLASS_ID',
'  and ROLE_ID in (select ROLE_ID',
'                  from STS_ROLE',
'                  where ROLE_TYPE = ''SUPER_ADMIN'' and IS_ENABLE = 1 and DEL_FLAG = 0 and TENANT_ID = :USER_TENANT)',
