unistr('    V_FOLDER_CLASS_ID  NUMBER(20); --\539F\6765\7684\5206\7C7BID'),
unistr('    V_FOLDER_CLASS_NAME_OLD  VARCHAR2(45);--\539F\6765\7684\5206\7C7B\540D\79F0'),
