,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'V_ERR_MSG            NVARCHAR2(2000);',
'V_FOLDER_CLASS_ID    NUMBER(20);',
'V_FOLDER_CLASS_LEVEL NUMBER(20);',
'V_IS_INSERT          NUMBER(20);',
'V_COUNT              NUMBER(20);',
'CURSOR ADDUSERCURSOR IS SELECT COLUMN_VALUE',
'FROM TABLE (SPLITSTR(:P123_USER_IDS, '',''))',
'MINUS',
'SELECT COLUMN_VALUE',
'FROM TABLE (SPLITSTR(:P123_USER_IDS_RAW, '',''));',
'CURSOR ADDDEPTCURSOR IS SELECT COLUMN_VALUE',
'FROM TABLE (SPLITSTR(:P123_DEPT_IDS, '',''))',
'MINUS',
'SELECT COLUMN_VALUE',
'FROM TABLE (SPLITSTR(:P123_DEPT_IDS_RAW, '',''));',
'BEGIN',
unistr('--\5206\7C7BID'),
'SELECT FOLDER_CLASS_ID INTO V_FOLDER_CLASS_ID FROM STS_FOLDER_LIB WHERE FOLDER_LIB_ID = :P123_FOLDER_LIB_ID;',
unistr('--\5206\7C7B\662F\5426\9700\8981\6DFB\52A0'),
'IF V_FOLDER_CLASS_ID IS NULL THEN',
'V_IS_INSERT := 0;',
'ELSE',
'SELECT FOLDER_CLASS_LEVEL',
'INTO V_FOLDER_CLASS_LEVEL',
'FROM STS_FOLDER_CLASS',
'WHERE FOLDER_CLASS_ID = V_FOLDER_CLASS_ID;',
'IF V_FOLDER_CLASS_LEVEL = 0 THEN',
'V_IS_INSERT := 0;',
'ELSE',
'V_IS_INSERT := 1;',
'END IF;',
'END IF;',
'',
'DELETE STS_SCOPE',
'WHERE REFERENCE_ID = :P123_FOLDER_LIB_ID',
'AND REFERENCE_TYPE = ''FOLDER_LIB''',
'AND RANGE_TYPE = ''USER''',
'AND RANGE_ID IN (SELECT COLUMN_VALUE',
'FROM TABLE (SPLITSTR(:P123_USER_IDS_RAW, '',''))',
'MINUS',
'SELECT COLUMN_VALUE',
'FROM TABLE (SPLITSTR(:P123_USER_IDS, '','')));',
'',
'DELETE STS_SCOPE',
'WHERE REFERENCE_ID = :P123_FOLDER_LIB_ID',
'AND REFERENCE_TYPE = ''FOLDER_LIB''',
'AND RANGE_TYPE = ''DEPT''',
'AND RANGE_ID IN (SELECT COLUMN_VALUE',
'FROM TABLE (SPLITSTR(:P123_DEPT_IDS_RAW, '',''))',
'MINUS',
'SELECT COLUMN_VALUE',
'FROM TABLE (SPLITSTR(:P123_DEPT_IDS, '','')));',
'-- WRITE_LOG(''JW'', ''SCOPE2'',111, NULL, 1);',
'FOR CUR IN ADDUSERCURSOR',
'LOOP',
'INSERT INTO STS_SCOPE (CREATED_BY,',
'CREATION_DATE,',
'UPDATED_BY,',
'RANGE_TYPE,',
'RANGE_ID,',
'REFERENCE_ID,',
'REFERENCE_TYPE,',
'PERMISSIONS_TYPE,',
'SOURCE_USER_ID)',
'VALUES (:MPF_USER_ID,',
'SYSDATE,',
':MPF_USER_ID,',
'''USER'',',
'CUR.COLUMN_VALUE,',
':P123_FOLDER_LIB_ID,',
'''FOLDER_LIB'',',
'''VIEW'',',
':MPF_USER_ID);',
unistr('--\5206\7C7B'),
'IF V_IS_INSERT = 1 THEN',
'SELECT COUNT(SCOPE_ID)',
'INTO V_COUNT',
'FROM STS_SCOPE',
'WHERE REFERENCE_ID = V_FOLDER_CLASS_ID',
'AND REFERENCE_TYPE = ''FOLDER_CLASS''',
'AND RANGE_TYPE = ''USER''',
'AND RANGE_ID = CUR.COLUMN_VALUE;',
'IF V_COUNT = 0 THEN',
'INSERT INTO STS_SCOPE (CREATED_BY,',
'CREATION_DATE,',
'UPDATED_BY,',
'RANGE_TYPE,',
'RANGE_ID,',
'REFERENCE_ID,',
'REFERENCE_TYPE,',
'PERMISSIONS_TYPE,',
'SOURCE_USER_ID)',
'VALUES (:MPF_USER_ID,',
'SYSDATE,',
':MPF_USER_ID,',
'''USER'',',
'CUR.COLUMN_VALUE,',
'V_FOLDER_CLASS_ID,',
'''FOLDER_CLASS'',',
'''VIEW'',',
':MPF_USER_ID);',
'END IF;',
'END IF;',
'END LOOP;',
'',
'FOR CUR IN ADDDEPTCURSOR',
'LOOP',
'INSERT INTO STS_SCOPE (CREATED_BY,',
'CREATION_DATE,',
'UPDATED_BY,',
'RANGE_TYPE,',
'RANGE_ID,',
'REFERENCE_ID,',
'REFERENCE_TYPE,',
'PERMISSIONS_TYPE,',
'SOURCE_USER_ID)',
'VALUES (:MPF_USER_ID,',
'SYSDATE,',
':MPF_USER_ID,',
'''DEPT'',',
'CUR.COLUMN_VALUE,',
':P123_FOLDER_LIB_ID,',
'''FOLDER_LIB'',',
'''VIEW'',',
':MPF_USER_ID);',
unistr('--\5206\7C7B'),
'IF V_IS_INSERT = 1 THEN',
'SELECT COUNT(SCOPE_ID)',
'INTO V_COUNT',
'FROM STS_SCOPE',
'WHERE REFERENCE_ID = V_FOLDER_CLASS_ID',
'AND REFERENCE_TYPE = ''FOLDER_CLASS''',
'AND RANGE_TYPE = ''DEPT''',
'AND RANGE_ID = CUR.COLUMN_VALUE;',
'IF V_COUNT = 0 THEN',
'INSERT INTO STS_SCOPE (CREATED_BY,',
'CREATION_DATE,',
'UPDATED_BY,',
'RANGE_TYPE,',
'RANGE_ID,',
'REFERENCE_ID,',
'REFERENCE_TYPE,',
'PERMISSIONS_TYPE,',
'SOURCE_USER_ID)',
'VALUES (:MPF_USER_ID,',
'SYSDATE,',
':MPF_USER_ID,',
'''DEPT'',',
'CUR.COLUMN_VALUE,',
'V_FOLDER_CLASS_ID,',
'''FOLDER_CLASS'',',
'''VIEW'',',
':MPF_USER_ID);',
'END IF;',
'END IF;',
'END LOOP;',
'APEX_UTIL.SET_SESSION_STATE(''P123_ROW_COUNT'', 1);',
'COMMIT;',
'EXCEPTION',
'WHEN OTHERS THEN',
'ROLLBACK;',
'V_ERR_MSG := SQLERRM || CHR(13) || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;',
unistr('WRITE_LOG(''P'' || :APP_PAGE_ID || ''-\4FDD\5B58\53EF\89C1\8303\56F4'', ''ERROR'', V_ERR_MSG, :JW_USER_ID, :JW_USER_TENANT, :APP_NAME,'),
':APP_ID, :APP_CODE);',
'APEX_UTIL.SET_SESSION_STATE(''P123_ROW_COUNT'', -1);',
'END;'))
