'    });',
'}',
'function getUploadFileKey(uploadResult, file) {',
'    var fileKey;',
'    if (typeof uploadResult === "string") {',
'        fileKey = uploadResult;',
'    } else if (uploadResult && uploadResult.fileKey) {',
'        fileKey = uploadResult.fileKey;',
