'                            FROM TABLE (SPLITSTR(:P138_DEPT_IDS_RAW, '',''));',
'begin',
unistr('--\5220\9664\5386\53F2\6570\636E'),
'delete STS_SCOPE',
'where REFERENCE_ID = :P138_FILE_ID',
'and REFERENCE_TYPE = ''FILE''',
'and RANGE_TYPE = ''USER''',
