'    from STS_SCOPE',
'        where REFERENCE_TYPE =''FILE'' AND REFERENCE_ID =:P138_FILE_ID;',
'    END IF;',
'end loop;',
'    APEX_UTIL.SET_SESSION_STATE(''P138_ROW_COUNT'', 1);',
'    commit;',
'EXCEPTION',
