'BEGIN',
unistr('    -- \8C03\8BD5\8F93\51FA\5F52\6863\7C7B\578B'),
unistr('     JA_WRITE_LOG(''P'' || :APP_PAGE_ID || ''-\9ED8\8BA4\5F52\6863\8BBE\7F6E-P141_PLANS_FILE_TYPE:'' || :P141_PLANS_FILE_TYPE, ''info'', v_err_msg,'),
