'    )',
'    AND DEL_FLAG = 0',
'    AND TENANT_ID = :USER_TENANT;',
'',
'    v_row_count := SQL%ROWCOUNT;',
'    COMMIT;',
'    APEX_UTIL.SET_SESSION_STATE(''P141_ROW_COUNT'', v_row_count);',
'',
unistr('    -- \8C03\8BD5\8F93\51FA\66F4\65B0\7ED3\679C'),
