unistr('    v_PLANS_FILE_DATE DATE; --\8BA1\5212\5F52\6863\65F6\95F4'),
unistr('    v_file_status varchar2(255):= ''NORMAL''; --\6587\4EF6\72B6\6001,\9ED8\8BA4\6B63\5E38'),
'    /**',
'     * create by: wxx',
'     * create date:2025/5/20   14:40',
