'',
unistr('    -- 2. \4F7F\7528\66F4\5B89\5168\7684TABLE\51FD\6570\8BED\6CD5'),
'    UPDATE STS_FILE ',
'    SET PLANS_FILE_TYPE = ''IMMEDIATELY'',',
'        PLANS_FILE_DATE = v_plans_file_date,',
