unistr('        v_err_msg := ''\6587\4EF6ID: '' || :P143_FILE_ID || '' \9519\8BEF: '' || SQLERRM || CHR(13) || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;'),
unistr('        JA_WRITE_LOG(''P'' || :APP_PAGE_ID || ''-\6587\4EF6\7ACB\5373\5F52\6863\8BBE\7F6E'', ''ERROR'', v_err_msg,'),
