'       SYSDATE,',
'       :MPF_USER_ID,',
'       SYSDATE,',
'       RANGE_TYPE,',
'       RANGE_ID',
'FROM STS_SCOPE',
'WHERE REFERENCE_TYPE = ''FILE''',
'  AND REFERENCE_ID = :P146_PARENT_FOLDER_ID;',
'        END IF;',
'    END LOOP;',
'COMMIT;',
unistr('--\8C03\7528\63A5\53E3'),
'V_FILE_IDS := SUBSTR(V_FILE_IDS, 1, length(V_FILE_IDS) - 1);',
