' /**',
' * CREATE BY: WXX',
' * CREATE DATE: 2025/5/22 16:30',
unistr(' * DESCRIBE: \539F\6587\4EF6\5F52\6863'),
' */',
'BEGIN',
'    v_plans_file_date := TRUNC(SYSDATE, ''MI'');',
'',
'    UPDATE STS_FILE',
'    SET PLANS_FILE_TYPE = ''IMMEDIATELY'',',
'        PLANS_FILE_DATE = v_plans_file_date,',
