'if($v(''P154_PROCESSED_COUNT'')>0){',
unistr('    alert(''\6587\4EF6\8FC1\79FB\6210\529F'');'),
'    return true;',
'}else{',
unistr('    alert(''\6587\4EF6\8FC1\79FB\5931\8D25'');'),
'    return false;',
'}'))
);
