'from (',
'    select role.ROLE_ID, role.ROLE_NAME',
'      from STS_USER_ROLE u',
'      join STS_ROLE role',
'        on role.ROLE_ID = u.ROLE_ID',
'       and role.TENANT_ID = u.TENANT_ID',
'       and role.DEL_FLAG = 0',
'     where u.USER_ID = :MPF_USER_ID',
'       and u.DEL_FLAG = 0',
'       and u.IS_ENABLE = 1',
'       and u.TENANT_ID = :USER_TENANT',
'     group by role.ROLE_ID, role.ROLE_NAME',
'    union',
'    select role.ROLE_ID, role.ROLE_NAME',
'      from STS_ROLE role',
'     where role.ROLE_TYPE = ''FOLDER_REPORT''',
'       and role.DEL_FLAG = 0',
'       and role.IS_ENABLE = 1',
'       and role.TENANT_ID = :USER_TENANT',
'       and not exists (',
'             select 1',
'               from STS_USER_ROLE u',
'              where u.USER_ID = :MPF_USER_ID',
'                and u.ROLE_ID = role.ROLE_ID',
'                and u.DEL_FLAG = 0',
'                and u.IS_ENABLE = 1',
'                and u.TENANT_ID = :USER_TENANT',
'       )',
'       and exists (',
'             select 1',
'               from STS_SCOPE s',
'              where s.REFERENCE_TYPE in (''FOLDER_LIB'', ''FOLDER'', ''FILE'')',
'                and s.PERMISSIONS_TYPE = ''MANAGE''',
'                and (',
'                      (s.RANGE_TYPE = ''USER'' and s.RANGE_ID = :DIAN_USER_ID)',
'                   or (s.RANGE_TYPE = ''DEPT'' and exists (',
'                          select 1',
'                            from BASIC_JA_DING_DEPT_USER d',
'                           where to_char(d.DEPT_ID) = s.RANGE_ID',
'                             and d.USER_ID = :DIAN_USER_ID',
'                      ))',
'                )',
'       )',
') role_list',
'order by role_list.ROLE_NAME'))
