'    v_tenant_id      number(10);',
'    V_TEMP           VARCHAR2(2000);',
'    V_page           VARCHAR2(100);',
'begin',
'    if apex_application.g_x02 = ''code_login'' then',
'        v_request_url := v_code_login_url;',
'    else',
'        v_request_url := v_auto_login_url;',
'    end if;',
'',
'    V_TEMP := SUBSTRING_INSTR2(v_url, '':::::'', 1, 2);',
