'            :P99999_USERNAME := apex_authentication.get_login_username_cookie;',
'            :P99999_REMEMBER := case when :P99999_USERNAME is not null then ''Y'' end;',
'        end if;',
'    else',
'        :P99999_USERNAME := apex_authentication.get_login_username_cookie;',
'        :P99999_REMEMBER := case when :P99999_USERNAME is not null then ''Y'' end;',
'    end if;',
'',
'exception',
'    when others then',
'        v_err_msg := sqlerrm || chr(13) || dbms_utility.format_error_backtrace;',
